/**
 * @method
 * @name scwin.sel
 * @author Inswave
 * @date 2026. 09. 29
 * @param jaum
 * @returns
 * @hidden N
*/
scwin.sel = async function (jaum) {
    /* sdd-asis-lifecycle:begin sel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var obj = (document.frm || { elements: [] });
    var iCount = 0;
    scwin.arrReset();
    for (var j = 0; j < jr.length; j++) {
        if (jr[j] != null && jaum === jr[j].jtt) {
            if (scwin.flag !== 'true') {
                if (jr[j].jname.indexOf("변경전사명") < 1) {
                    if (scwin.regcncl === "1") {
                        scwin.arrCode[iCount] = jr[j].jcode;
                        scwin.arrName[iCount] = jr[j].jname;
                        iCount++;
                    } else {
                        if (jr[j].jname.indexOf("폐지") < 1) {
                            scwin.arrCode[iCount] = jr[j].jcode;
                            scwin.arrName[iCount] = jr[j].jname;
                            iCount++;
                        }
                    }
                }
            } else {
                if (scwin.regcncl === "1") {
                    scwin.arrCode[iCount] = jr[j].jcode;
                    scwin.arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        scwin.arrCode[iCount] = jr[j].jcode;
                        scwin.arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    await scwin.setSelectBox();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setSelectBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param
