 * @hidden N
*/
scwin.setSelectBox = async function () {
    /* sdd-asis-lifecycle:begin setSelectBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var obj = (document.frm || { elements: [] });
    $c.util.getComponent('slc_selCode').options.length = scwin.arrCode.length;
    for (i = 0; i < scwin.arrCode.length; i++) {
        $c.util.getComponent('slc_selCode').getItemText(i) = '(' + scwin.arrCode[i] + ')' + scwin.arrName[i];
        $c.util.getComponent('slc_selCode').options[i].value = scwin.arrCode[i];
    }
    if (scwin.arrCode.length != 0) {
        $c.util.getComponent("ipt_codeName").setValue(scwin.arrName[0]);
        $c.util.getComponent('slc_selCode').setSelectedIndex(0);
        $c.util.getComponent("slc_selCode").focus();
    } else {
        await $c.win.alert('해당 종목이 존재하지 않습니다.');
    }
    /* sdd-asis-lifecycle:end */
};


