    /* sdd-asis-lifecycle:begin searchCom — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var obj = (document.frm || { elements: [] });
    var searchValue = $c.util.getComponent('ipt_codeName').getValue();
    if (searchValue.length != 0) {
        if (scwin.isNumber(searchValue)) {
            await scwin.searchCode(searchValue);
        } else {
            await scwin.searchName(searchValue);
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNumber
 * @author Inswave
 * @date 2026. 09. 29
 * @param searchValue
 * @returns
 * @hidden N
*/
scwin.isNumber = function (searchValue) {
    /* sdd-asis-lifecycle:begin isNumber — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var numCheck = /^[0-9]+$/;
    if (numCheck.test(searchValue)) {
        return true;
    } else {
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


