*/
scwin.findcode = function (jcode) {
    /* sdd-asis-lifecycle:begin findcode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var name = '';
    for (var j = 0; j < jr.length; j++) {
        if (jr[j].jcode === jcode) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                name = jr[j].jname;
                break;
            }
        }
    }
    return name;
    /* sdd-asis-lifecycle:end */
};
